onRoleReachedMoon = function()     game.pauseLogic()	if global.getBool("lvl42_b1") then dialog.setSkipEnabled(true) end		repeat			sound.play("54-1")		    if dialog.show("Level42-1", faceManyi) ==1 then break end			if dialog.show("Level42-2", faceBujie) ==1 then break end			if dialog.show("Level42-3", faceWunai) ==1 then break end			sound.play("50-1")			if dialog.show("Level42-4", facePutong) ==1 then break end			if dialog.show("Level42-5", faceManyi) ==1 then break end			global.setBool("lvl42_b1")		until true		dialog.setSkipEnabled(false)    game.success()end